      { status: "in_review", submitted_at: new Date() },
      { status: "approved", reviewed_by: reviewerId, reviewed_at: new Date() },
      { status: "published", published_by: adminId, published_at: new Date() },
    ];
    let version = v.version;
    for (const s of steps) {
      version += 1;
