    await publishAsOwner(rule.id as string, 1);
    const create = (session: Session) =>
      call<Body>(api.app, "POST", `${R}/${rule.id}/versions`, {
        session,
        headers: ifm(2),
        body: { changeSummary: "Synthetic second version" },
